import{_ as s,o as t,c as i,a0 as o}from"./chunks/framework.ChlVJx0I.js";const d=JSON.parse('{"title":"The skill tree tracks upstream sources with per-source pins","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0013-skill-tree-tracks-upstream-sources-with-per-source-pins.md","filePath":"adr/0013-skill-tree-tracks-upstream-sources-with-per-source-pins.md","lastUpdated":1789552050000}'),r={name:"adr/0013-skill-tree-tracks-upstream-sources-with-per-source-pins.md"};function a(l,e,n,c,p,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="the-skill-tree-tracks-upstream-sources-with-per-source-pins" tabindex="-1">The skill tree tracks upstream sources with per-source pins <a class="header-anchor" href="#the-skill-tree-tracks-upstream-sources-with-per-source-pins" aria-label="Permalink to &quot;The skill tree tracks upstream sources with per-source pins&quot;">​</a></h1><p>The package ships a skill tree of full skill copies. Tracked skills come from upstream repos (Matt Pocock&#39;s skills repo today, MIT licensed). Local tweaks are edits to the copies in place. A skill sync three-way-merges each tracked file - base is the file at the Source pin, theirs is the file at the fetched commit, ours is the local copy - and advances the pin only when the whole source merges clean. The tracking unit is the repo, not the file: one pin per Skill source.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Per-skill commit pins.</strong> Each skill records its own last-synced commit, so every merge base is as fresh as possible for that skill. Rejected: the sync state doubles, and a partially completed sync leaves a spread of pins that no single upstream commit represents. Following a repo is the unit the user wants to reason about; one pin that names &quot;the commit where the whole tree last agreed&quot; is simpler to inspect and to trust.</li><li><strong>Patch files (quilt-style).</strong> Pristine upstream copies plus per-skill <code>.patch</code> files applied with <code>git apply --3way</code>. Rejected: patches and content live in two places, patch files break often as upstream moves, and every upstream change costs a rebase.</li><li><strong>Git subtree of the upstream repo plus patched copies.</strong> Git-native history, but merging upstream movement into the patched copies is a manual, unstructured diff between two trees. No per-file conflict against the copies the user actually edits.</li><li><strong>Overlay (pristine copies plus whole-file overrides).</strong> Rejected: it cannot express a line-level instruction tweak without replacing the whole file, and upstream updates to an overridden file are silently dropped.</li><li><strong>Pi extension with an in-pi update command.</strong> Rejected: updating skills is a repo chore, not an agent function. A plain script in the repo is the right shape, and pi loads the tree by itself through the conventional <code>skills/</code> directory.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The layout is the manifest: <code>skills/&lt;source-slug&gt;/&lt;upstream bucket&gt;/&lt;name&gt;</code>. A tracked skill&#39;s upstream path is read off its local path, so the manifest holds one entry per source - repo URL, local root, pin. Local-only skills live under <code>skills/local/</code> and are invisible to sync.</li><li>Pin advancement is all-or-nothing per source. One unresolved conflict holds the pin for the whole source, so the pin always names a commit at which every tracked skill is in agreement.</li><li>Conflicts surface as git conflict markers in the file, resolved in a normal session, and the pin advances on the next clean sync.</li><li>The tool never commits or pushes. Publishing is the user&#39;s act.</li><li>A second upstream repo is one manifest entry and one <code>skills/&lt;source&gt;/</code> root, not a redesign.</li></ul>',6)])])}const m=s(r,[["render",a]]);export{d as __pageData,m as default};
